#!/usr/bin/env python3
from pathlib import Path
import re

src = Path('src/Meltype.Android/MeltypeInputMethodService.cs')
text = src.read_text(encoding='utf-8')

def r(old, new):
    global text
    c = text.count(old)
    if c != 1:
        raise SystemExit(f'expected one match, got {c}: {old[:120]!r}')
    text = text.replace(old, new, 1)

def rr(pattern, repl):
    global text
    text2, count = re.subn(pattern, repl, text, flags=re.S)
    if count != 1:
        raise SystemExit(f'expected one regex match, got {count}: {pattern[:120]!r}')
    text = text2

